using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps;using MapSharedProps.EditorTools;
// 茂みだけの共有資産・既存v1読取・GPU変形・接触・実描画を隔離D3D11で確認する。
public static class BushVolumeChecks {
 [Serializable]class Model{public string id;public float[] world,touch;}[Serializable]class Fixture{public float[] matrix,direction,rootSlope;public float time,strength;public Model[] models;}
 [Serializable]class Row{public string name,detail;public bool passed;}[Serializable]class Report{public string status;public Row[] checks;}
 static List<Row> checks=new List<Row>();static void Verify(string name,bool ok,string detail=""){checks.Add(new Row{name=name,passed=ok,detail=detail});if(!ok)throw new Exception(name+": "+detail);}static string Arg(string key){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,key)+1];}
 public static void Run(){string output=Arg("-nature-output"),export=Path.Combine(output,"bare-export");int code=0;try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var lib=MapSharedPropsBuilder.ReadLibrary(Path.Combine(export,"shared_props.json"));var built=MapSharedPropsBuilder.Build(export);Verify("50 models and eight original-ID placements",built.prefabs.Count==50&&built.placed==8&&built.skipped==0);var a=Array.Find(lib.assets,x=>x.id=="bush");var prefab=built.prefabs["bush"];var mesh=prefab.GetComponent<MeshFilter>().sharedMesh;var material=prefab.GetComponent<Renderer>().sharedMaterial;
  Verify("bush v2, 184 triangles, one cutout material",a.version==2&&mesh.triangles.Length/3==184&&prefab.GetComponent<Renderer>().sharedMaterials.Length==1&&Mathf.Abs(material.GetFloat("_Cutoff")-.42f)<1e-6f);var p=mesh.vertices;var n=mesh.normals;var c=mesh.colors;var uv=mesh.uv;var w=mesh.uv2;float error=0;for(int i=0;i<p.Length;i++){error=Mathf.Max(error,Vector3.Distance(p[i],new Vector3(a.positions[i*3],a.positions[i*3+1],a.positions[i*3+2])),Vector3.Distance(n[i],new Vector3(a.normals[i*3],a.normals[i*3+1],a.normals[i*3+2])),Vector2.Distance(uv[i],new Vector2(a.uv[i*2],a.uv[i*2+1])),Mathf.Abs(c[i].r-a.colors[i*3]),Mathf.Abs(w[i].x-a.motionWeights[i*2]),Mathf.Abs(w[i].y-a.motionWeights[i*2+1]));}Verify("Canonical geometry, colours, UV and wind/contact masks",error<1e-6f,"error="+error);
  var legacy=MapSharedPropsBuilder.ReadLibrary(Path.Combine(Arg("-bush-legacy"),"shared_props.json"));var old=Array.Find(legacy.assets,x=>x.id=="bush");Verify("Previous shared bush v1 remains accepted",old!=null&&old.version==1&&old.material.alphaCutoff==0);
  var f=JsonUtility.FromJson<Fixture>(File.ReadAllText(Path.Combine(output,"motion-probe-expected.json")));var matrix=new Matrix4x4();for(int r=0;r<4;r++)for(int k=0;k<4;k++)matrix[r,k]=f.matrix[k*4+r];Probe(a,mesh,material,matrix,f,Array.Find(f.models,x=>x.id=="bush"));var still=new Fixture{matrix=f.matrix,direction=f.direction,time=2.4f,strength=0};var expected=new Model{id="bush",touch=new float[]{0,0},world=new float[p.Length*3]};for(int i=0;i<p.Length;i++){var q=matrix.MultiplyPoint3x4(p[i]);expected.world[i*3]=q.x;expected.world[i*3+1]=q.y;expected.world[i*3+2]=q.z;}Probe(a,mesh,material,matrix,still,expected);
  var manager=built.root.GetComponent<SharedPlantContact>();var entry=manager.entries.Find(e=>e.renderer.sharedMaterial==material);Verify("bush contact source registered",entry!=null);var actor=new GameObject("Actor feet");var source=actor.AddComponent<SharedPlantContactSource>();source.height=1.8f;source.radius=.3f;manager.source=source;manager.useClock=false;var originalScale=entry.renderer.transform.localScale;var origin=entry.renderer.transform.position;
  foreach(float scale in new[]{1f,.6f}){entry.renderer.transform.localScale=originalScale*scale;actor.transform.position=origin+new Vector3(-2,0,.12f);manager.Step(.016f);float peak=0;for(int k=0;k<180;k++){actor.transform.position=origin+new Vector3(-2+k*.025f,0,.12f);manager.Step(1/60f);peak=Mathf.Max(peak,entry.bend.magnitude);}actor.transform.position=origin+new Vector3(-.2f,0,.12f);for(int k=0;k<1200;k++)manager.Step(1/60f);Verify("Continuous contact bounded at scale "+scale,peak>0&&peak<=a.contact.maxDisplacementMetres*scale+.00001f&&entry.bend.magnitude<=a.contact.maxDisplacementMetres*scale+.00001f,"peak="+peak);actor.transform.position=origin+new Vector3(100,0,100);for(int k=0;k<360;k++)manager.Step(1/60f);Verify("Contact recovers at scale "+scale,entry.bend==Vector2.zero);}var after=mesh.vertices;for(int i=0;i<p.Length;i++)Verify("Fixed source vertex "+i,p[i]==after[i]);UnityEngine.Object.DestroyImmediate(built.root);UnityEngine.Object.DestroyImmediate(actor);
  var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var rp=UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=40;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.white;var sun=new GameObject("Preview sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1;sun.shadows=LightShadows.Hard;sun.shadowBias=.01f;sun.shadowNormalBias=.02f;sun.gameObject.AddComponent<UniversalAdditionalLightData>().usePipelineSettings=false;sun.transform.rotation=Quaternion.LookRotation(new Vector3(3,-8,5));var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.localScale=Vector3.one*6;var fm=built.ground.material;fm.SetVector("_EditorZero",Vector4.zero);floor.GetComponent<Renderer>().sharedMaterial=fm;var obj=(GameObject)PrefabUtility.InstantiatePrefab(prefab);obj.transform.position=new Vector3(0,-.05f,0);obj.transform.rotation=Quaternion.Euler(0,-22.345f,0);var renderer=obj.GetComponent<Renderer>();var person=GameObject.CreatePrimitive(PrimitiveType.Capsule);person.transform.localScale=new Vector3(.35f,.9f,.35f);person.transform.position=new Vector3(1.7f,.9f,0);var camera=new GameObject("Bush camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.orthographic=true;camera.orthographicSize=2.2f;camera.aspect=1.6f;camera.farClipPlane=100;
  foreach(bool dirt in new[]{true,false})foreach(bool top in new[]{true,false}){fm.SetFloat("_DirtWeight",dirt?1:0);camera.transform.position=top?new Vector3(.6f,8,0):new Vector3(3.6f,4.6f,6.5f);camera.transform.up=top?Vector3.forward:Vector3.up;camera.transform.LookAt(new Vector3(.6f,top?0:.3f,0));Shader.SetGlobalVector("_TDPineOrigin",Vector4.zero);foreach(var state in new[]{new Vector3(0,0,0),new Vector3(2.4f,0,0),new Vector3(0,.7f,0),new Vector3(2.4f,.7f,0),new Vector3(2.4f,.7f,.16f)}){Shader.SetGlobalVector("_TDPineWind",new Vector4(.8f,.6f,state.y,state.x));var block=new MaterialPropertyBlock();block.SetVector("_PlantTouch",new Vector4(state.z,0,0,0));renderer.SetPropertyBlock(block);Capture(camera,output,"unity-bush-"+(dirt?"dirt":"grass")+"-"+(top?"top":"walk")+"-"+state.x+"-"+state.y+"-"+state.z+".png");}Verify("Rendered bush and shadow on "+(dirt?"dirt":"grass")+" "+(top?"top":"walk"),renderer.sharedMaterial.shader.isSupported);}
  var messages=ShaderUtil.GetShaderMessages(Shader.Find("MapSharedProps/Lit"));bool good=true;foreach(var msg in messages)if(msg.severity.ToString()=="Error")good=false;Verify("No shared shader errors",good);
 }catch(Exception e){code=1;Debug.LogException(e);checks.Add(new Row{name="Unexpected failure",passed=false,detail=e.ToString()});}File.WriteAllText(Path.Combine(output,"bush-unity.json"),JsonUtility.ToJson(new Report{status=code==0?"Passed":"Failed",checks=checks.ToArray()},true));EditorApplication.Exit(code);}
 static void Probe(MapSharedPropsBuilder.AssetDto a,Mesh mesh,Material material,Matrix4x4 matrix,Fixture fixture,Model expected){int n=mesh.vertexCount;var positions=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);var masks=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);positions.filterMode=masks.filterMode=FilterMode.Point;var p=new Color[n];var w=new Color[n];for(int i=0;i<n;i++){p[i]=new Color(a.positions[i*3],a.positions[i*3+1],a.positions[i*3+2],a.uv[i*2+1]);w[i]=a.motionWeights!=null?new Color(a.motionWeights[i*2],a.motionWeights[i*2+1],a.rootWeights!=null?a.rootWeights[i]:0,0):Color.clear;}positions.SetPixels(p);positions.Apply();masks.SetPixels(w);masks.Apply();var probe=new Material(Shader.Find(fixture.rootSlope==null?"Hidden/MapSharedProps/PlantMotionProbe":"Hidden/MapSharedProps/RootGroundingProbe"));if(fixture.rootSlope!=null)probe.SetVector("_TDRootSlope",new Vector4(fixture.rootSlope[0],fixture.rootSlope[1],0,0));probe.SetTexture("_Masks",masks);probe.SetMatrix("_ProbeMatrix",matrix);probe.SetVector("_PineBand",material.GetVector("_PineBand"));probe.SetVector("_PineWaves",material.GetVector("_PineWaves"));probe.SetVector("_PinePhase",material.GetVector("_PinePhase"));probe.SetVector("_PineResponse",material.GetVector("_PineResponse"));probe.SetFloat("_PlantCombinedLimit",material.GetFloat("_PlantCombinedLimit"));probe.SetVector("_PlantTouch",new Vector4(expected.touch[0],expected.touch[1],0,0));Shader.SetGlobalVector("_TDPineOrigin",Vector4.zero);Shader.SetGlobalVector("_TDPineWind",new Vector4(fixture.direction[0],fixture.direction[1],fixture.strength,fixture.time));var rt=new RenderTexture(n,1,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);rt.Create();Graphics.Blit(positions,rt,probe);var previous=RenderTexture.active;RenderTexture.active=rt;var read=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);read.ReadPixels(new Rect(0,0,n,1),0,0);read.Apply();var pixels=read.GetPixels();float error=0,rootError=0;for(int i=0;i<n;i++){var want=new Vector3(expected.world[i*3],expected.world[i*3+1],expected.world[i*3+2]);var actual=new Vector3(pixels[i].r,pixels[i].g,pixels[i].b);error=Mathf.Max(error,Vector3.Distance(want,actual));if(IsFixed(a,material,i))rootError=Mathf.Max(rootError,Vector3.Distance(actual,RootReference(matrix,mesh.vertices[i],a.rootWeights!=null?a.rootWeights[i]:0,fixture.rootSlope)));}Verify(a.id+" GPU agrees with browser and fixed anchors",error<.00002f&&rootError<.000003f,"error="+error+", roots="+rootError);RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(read);UnityEngine.Object.DestroyImmediate(positions);UnityEngine.Object.DestroyImmediate(masks);UnityEngine.Object.DestroyImmediate(probe);}
 static Vector3 RootReference(Matrix4x4 m,Vector3 p,float weight,float[] slope){var v=m.MultiplyPoint3x4(p);if(slope!=null){var origin=m.MultiplyPoint3x4(Vector3.zero);v.y+=((v.x-origin.x)*slope[0]+(v.z-origin.z)*slope[1])*weight;}return v;}
 static bool IsFixed(MapSharedPropsBuilder.AssetDto a,Material material,int i){if(a.motionWeights!=null)return a.motionWeights[i*2]==0&&a.motionWeights[i*2+1]==0;var b=material.GetVector("_PineBand");return a.positions[i*3+1]<=b.x||(a.id=="pine"&&a.uv[i*2+1]<=.5f);}
 static void Capture(Camera camera,string output,string name){var rt=new RenderTexture(1280,800,24);rt.Create();camera.targetTexture=rt;RenderPipeline.SubmitRenderRequest(camera,new RenderPipeline.StandardRequest{destination=rt});var old=RenderTexture.active;RenderTexture.active=rt;var im=new Texture2D(1280,800,TextureFormat.RGBA32,false);im.ReadPixels(new Rect(0,0,1280,800),0,0);im.Apply();File.WriteAllBytes(Path.Combine(output,name),im.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(im);}
}
